object RewardsData {
    /* Ten points to the rand, in one place. A screen that wants to show what a balance is
       worth multiplies by this; a screen that hard-codes 'R10' has created a second copy of a
       number that will be wrong the day this one changes. */
    const val randPerPoint = 0.1
    const val expiryMonths = 18
    const val warnBeforeExpiryDays = 60
    val tierInputs = listOf("points earned in the last 12 months")

    fun randValue(points: Int) = points * randPerPoint
    fun tierForPoints(points: Int) = rewardTiers.sortedByDescending { it.from }.firstOrNull { points >= it.from } ?: rewardTiers[0]
    fun reason(id: String) = rewardEarnReasons.firstOrNull { it.id == id }
    fun refusal(id: String) = rewardRefusals.firstOrNull { it.id == id }
}
